import React from 'react';
import {Navigate } from 'react-router-dom';

const PrivateRoute = ({ element } : React.ReactNode) => {
  const userDataStr  = localStorage.getItem('userData');
  const token = localStorage.getItem('token');
  const tokenExpirationTimestr = localStorage.getItem('tokenExpirationTime');
  const currentDate = new Date();

  let userData: { token: string; tokenExpirationMinutes: number } | null = null;
  if (userDataStr) {
    try {
      userData = JSON.parse(userDataStr);
    } catch (error) {
      console.error("Error parsing userData:", error);
    }
  }
  const tokenExpirationTime = userData
    ? new Date(new Date().getTime() + userData.tokenExpirationMinutes * 60000) // Token expiration based on minutes
    : null;
  const isTokenValid = tokenExpirationTime > currentDate;
  // If user data exists, allow access to the route
  // Otherwise, redirect to the login page
  console.log("User Data : ",userData)
  console.log("Token : ",token)
  console.log("Login Time : ",localStorage.getItem('loginTime'))
  console.log("Token Expiration Time : ",tokenExpirationTime.toString())
  console.log("Current Date : ", currentDate.toString())
  console.log("Is Token Valid ? : ",isTokenValid)
  return userData ? (userData.userId > 0 && token != null && isTokenValid) ? element : <Navigate to="/login" /> : <Navigate to="/login"/>;
};

export default PrivateRoute;
